contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the fuzzer will call
    function run(address targetContract, address asset) public payable {
        require(true);

        // Read pending decision for this contract (msg.sender for c calls is address(this))
        (uint256 before_amount, uint256 before_unlock, address before_asset, , ) = c.pendingFlashDecision(targetContract, address(this));

        // Attempt the call and capture whether it reverted.
        bool reverted;
        try c.withdrawGovernanceAsset{value: 0}(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after state
        (uint256 after_amount, uint256 after_unlock, address after_asset, , ) = c.pendingFlashDecision(targetContract, address(this));

        // If the call succeeded (didn't revert), it must have met the require conditions:
        // - before_asset == asset
        // - before_amount > 0
        // - before_unlock < block.timestamp
        // And the call must have deleted the pendingFlashDecision entry (amount==0 afterward).
        // If it reverted, at least one of those preconditions must have been false.
        assert(
            (!reverted && before_asset == asset && before_amount > 0 && before_unlock < block.timestamp && after_amount == 0)
            || (reverted && ( !(before_asset == asset && before_amount > 0 && before_unlock < block.timestamp) || after_amount == before_amount ))
        );
    }

    receive() external payable {}
}

