contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test entry point
    function run(address caller, int256 v1, int256 v2) public payable {
        require(caller != address(0));

        // Observe whether enforcement is active for the caller and whether caller is configured
        // We can only observe via public functions: enforceLimitsActive has public getter? It's declared mapping public? In C it's mapping(address => bool) public governed; enforceLimitsActive is not public. But there's setEnforcement and Configurable(configured()) for msg.sender.
        // We cannot call Configurable(caller).configured() unless caller is a contract implementing Configurable. We'll treat two scenarios by toggling enforcement on c from this contract before calling enforceTolerance, then call enforceTolerance as if from caller by invoking c.enforceTolerance via this contract (msg.sender will be this contract). Because the contract's checks use msg.sender, we can only influence when msg.sender == address(this). So we must reason about enforcement for address(this).

        // Setup: ensure this contract's enforcement flag is first set to true or false according to input 'caller' low bit.
        bool wantEnforce = (uint160(caller) & 1) == 1;
        c.setEnforcement(wantEnforce);

        // Also we cannot flip Configurable(caller).configured(); the enforceTolerance checks Configurable(msg.sender).configured(), so it will call Configurable(address(this)).configured(). We cannot change code of this contract, but we can implement configured() by making this contract itself implement that function via fallback/receive? Not allowed. However Configurable is an external contract; calling Configurable(msg.sender).configured() will call back to this contract. So implement receive/fallback to return configured? But only C calls Configurable(msg.sender).configured() as view; it expects an external call to our contract's configured(). We can provide it by adding a receive or fallback that returns data. But function signatures: configured() is function configured() public view returns (bool). When C calls Configurable(msg.sender).configured(), it performs an external call expecting ABI-encoded bool. Our InvMutTest can implement a public function configured() returning desired bool. But allowed functions: only constructor, receive, fallback; spec allowed receive and fallback. But we can implement fallback to handle that ABI and return bytes encoding bool. But fallback cannot be view. However external call will invoke fallback payable and we can return data. That's allowed.

        // We will set a mode bit: use second bit of caller to decide configured() return value
        bool wantConfigured = (uint160(caller) & 2) != 0;
        // store mode in contract state
        _mode = (wantConfigured ? 1 : 0) | (wantEnforce ? 2 : 0);

        // Now call enforceTolerance on c with absolute values of v1,v2 converted to uints via enforceToleranceInt path
        // We'll call enforceToleranceInt so negative handling is covered too.
        bool reverted;
        try c.enforceToleranceInt(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Now assert the general rule: if enforcement is not active for this contract OR this contract's configured() returns false, then the call must NOT revert.
        // We encoded wantEnforce in mode bit 2 and wantConfigured in bit 1. The rule: if !(wantEnforce && wantConfigured) then reverted == false.
        bool modeWantEnforce = (_mode & 2) != 0;
        bool modeWantConfigured = (_mode & 1) != 0;
        assert((!(modeWantEnforce && modeWantConfigured)) == (!reverted));
    }

    // store mode: bit0 = wantConfigured, bit1 = wantEnforce
    uint8 _mode;

    // Fallback to respond to configured() calls from c: return ABI-encoded bool equal to bit0 of _mode
    fallback() external payable returns (bytes memory) {
        // detect if the call data matches the selector of configured(): bytes4(keccak256("configured()"))
        bytes4 sel;
        if (msg.data.length >= 4) {
            assembly { sel := calldataload(0) }
        }
        bytes4 configuredSel = bytes4(keccak256("configured()"));
        if (sel == configuredSel) {
            bool b = (_mode & 1) != 0;
            bytes memory ret = new bytes(32);
            assembly { mstore(add(ret,32), b) }
            return ret;
        }
        return "";
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    // store mode: bit0 = wantConfigured (1 => configured() returns true), bit1 = wantEnforce (1 => setEnforcement(true))
    uint8 _mode;

    constructor(C _c) { c = _c; }

    // single test entry point
    function run(address dummyCaller, int256 v1, int256 v2) public payable {
        // dummyCaller is only used to provide variability; not otherwise used
        // decide desired flags from dummyCaller bits
        bool wantConfigured = (uint160(dummyCaller) & 1) != 0;
        bool wantEnforce = (uint160(dummyCaller) & 2) != 0;

        // record mode for fallback to read
        _mode = (wantConfigured ? 1 : 0) | (wantEnforce ? 2 : 0);

        // set enforcement flag for this contract in C
        c.setEnforcement(wantEnforce);

        // Call enforceToleranceInt and observe whether it reverts
        bool reverted;
        try c.enforceToleranceInt(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if NOT (enforcement active AND configured==true) then the call must NOT revert.
        // i.e., revert implies (wantEnforce && wantConfigured). Equivalently, if !(wantEnforce && wantConfigured) then reverted == false.
        assert((!(wantEnforce && wantConfigured)) == (!reverted));
    }

    // Fallback to respond to external configured() calls from C
    // Provide the ABI-encoded bool according to _mode bit0
    fallback(bytes calldata input) external payable returns (bytes memory) {
        // selector for configured() is bytes4(keccak256("configured()"))
        bytes4 configuredSel = bytes4(keccak256("configured()"));
        if (input.length >= 4) {
            bytes4 sel;
            assembly { sel := calldataload(input.offset) }
            if (sel == configuredSel) {
                bool b = (_mode & 1) != 0;
                bytes memory ret = new bytes(32);
                assembly { mstore(add(ret,32), b) }
                return ret;
            }
        }
        return "";
    }

    receive() external payable {}
}

