        bool wantEnforce = (uint160(modeSource) & 2) != 0;

        // store mode so our fallback can answer configured()
        mode = (wantConfigured ? 1 : 0) | (wantEnforce ? 2 : 0);

        // Set enforcement flag on c for this contract as a top-level state-changing call
        if (wantEnforce) {
            c.setEnforcement(true);
        } else {
            c.setEnforcement(false);
        }

        // Call enforceToleranceInt and record whether it reverts
        bool reverted;
        try c.enforceToleranceInt(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if it reverted then enforcement must have been active AND configured() must return true
        assert((!reverted) || (wantEnforce && wantConfigured));
    }

    // fallback to respond to configured() calls from c according to mode bit0
    fallback() external payable {
        // decode selector from calldata and if it's configured() selector, return bit0 as bool
        bytes4 sel;
        assembly { sel := calldataload(0) }
        if (sel == bytes4(keccak256("configured()"))) {
            bool b = (mode & 1) != 0;
            assembly {
                mstore(0x00, b)
                return(0x00, 0x20)
            }
