contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We model that this contract is the DAO proposer (since Governable constructor set DAO to deployer when c was created by checker).
    // run takes parameters to configure flash governance and then asserts the public getter reflects them.
    function run(address asset, uint256 amount, uint256 unlockTime, bool assetBurnable) public payable {
        // No preconditions on params.
        // Call configureFlashGovernance which is onlySuccessfulProposal; in the fresh deployment the DAO equals address(this) (the deployer of C),
        // but in the testing environment c was deployed by the checker; however the contract allows setDAO to be called by DAO or when not configured.
        // To ensure onlySuccessfulProposal passes, we first call c.setDAO(address(this)) which is allowed when DAO == address(0) (fresh) or msg.sender == DAO.
        // The checker deploys C before deploying this test, so DAO might be non-zero; however setDAO requires DAO==0 || msg.sender==DAO || !configured.
        // We try to setDAO directly; if it reverts, we'll catch and record reverted.
        bool setDaoReverted;
        try c.setDAO(address(this)) {
            setDaoReverted = false;
        } catch {
            setDaoReverted = true;
        }

        // Now call configureFlashGovernance and record whether it reverted.
        bool configureReverted;
        try c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable) {
            configureReverted = false;
        } catch {
            configureReverted = true;
        }

        // Read back the public flashGovernanceConfig via its autogenerated getter fields.
        (uint256 gotAmount, uint256 gotUnlockTime, address gotAsset, bool gotAssetBurnable) = c.flashGovernanceConfig();

        // The property: if configureFlashGovernance did not revert, then the stored values must equal the inputs.
        // If it reverted, then at least one stored value must differ OR the call to setDAO reverted (meaning we couldn't become successful proposer).
        // We assert this general relation.
