contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: attempt to withdraw a pending flash governance asset
    // Parameters: targetContract (address whose pending map we withdraw from), asset (asset address expected),
    // we also pass a gasless dummy amount param not used but required to vary inputs.
    function run(address targetContract, address asset, uint dummy) public payable {
        require(true);

        // Read the pending decision observable fields for msg.sender (this contract) before call
        (uint256 before_amount, uint256 before_unlockTime, address before_asset) = c.pendingFlashDecision(targetContract, address(this));

        // We'll attempt the withdraw and capture whether it reverted
        bool reverted;
        try c.withdrawGovernanceAsset{value: 0}(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call, read the pending decision again
        (uint256 after_amount, uint256 after_unlockTime, address after_asset) = c.pendingFlashDecision(targetContract, address(this));

        // Also observe c's balance change for the asset transfer by checking Ether balance only if asset is Ether (address(0) is not used by contract),
        // but we cannot observe ERC20 balances on c. So we assert the invariant relating pending state and revert behavior:
        // If call did not revert, then before_amount > 0, before_asset == asset, before_unlockTime < block.timestamp,
        // and after the call the pending entry must be cleared (amount == 0).
        // If it reverted, the pending entry must be unchanged.

        assert(
            reverted
            ? (after_amount == before_amount && after_unlockTime == before_unlockTime && after_asset == before_asset)
            : (
                // withdraw succeeded: require that there was a withdrawable pending entry before, matching asset and unlockTime passed
                before_amount > 0 && before_asset == asset && before_unlockTime < block.timestamp
                // and that the pending entry was deleted (amount == 0) after successful withdraw
                && after_amount == 0
            )
        );
    }

    receive() external payable {}
}

