            isERC20 = false;
            beforeBalance = 0;
        }

        // Attempt withdrawGovernanceAsset, capture whether it reverted.
        bool reverted;
        try c.withdrawGovernanceAsset(target, asset) {
            reverted = false;
        } catch {
            reverted = true;
