        (uint256 amtAfter, uint256 unlockAfter, address assetAfter, bool burnableAfter) = c.pendingFlashDecision(target, address(this));

        // If the withdraw call reverted, we assert nothing about deletion; but if it succeeded then the entry must be deleted
        // and the transferred amount must equal what was stored previously. We cannot read the "previous" pending entry if it
        // was deleted already; however the contract semantics guarantee that after a successful withdraw the entry is deleted.
