        // Build boolean for precondition as observed before the call.
        bool pre_asset_match = (before_asset == asset);
        bool pre_amount_positive = (before_amount > 0);
        // unlockTime < block.timestamp is equivalent to unlockTime < block.timestamp; we can observe before_unlockTime compared to block.timestamp
        bool pre_unlocked = (before_unlockTime < block.timestamp);
        bool preconds = pre_asset_match && pre_amount_positive && pre_unlocked;

        // Now assert the relationship between preconds, revert flag, and pending state after the call.
        // If preconds then must not revert and after_amount == 0 (cleared). If not preconds then must revert OR pending unchanged.
        assert(
            (preconds && !reverted && after_amount == 0) ||
            (!preconds && (reverted || (after_amount == before_amount && after_unlockTime == before_unlockTime && after_asset == before_asset && after_assetBurnable == before_assetBurnable)))
        );
    }

    receive() external payable {}
}

